<template>
  <div class="zg-container" v-loading="loading">
    <PageHeader :title="canMaintain ? '资料维护' : '资料查阅'" :eyebrow="canMaintain ? '知识库管理员' : '制度审核员'" description="集中查看制度正文、附件、表格和模板的来源与内容。"><template #actions><el-button v-if="isAdmin" @click="advancedVisible = true">高级维护</el-button><el-button v-if="canMaintain" type="primary" @click="packageVisible = true">添加资料</el-button></template></PageHeader>
    <div class="asset-status-strip"><span>资料 <b>{{ summary.assets }}</b></span><span>组成文件 <b>{{ summary.documents }}</b></span><span>待处理 <b>{{ pendingCount }}</b></span><span>处理受阻 <b class="danger">{{ summary.version_ingestion_states.blocked || 0 }}</b></span></div>
    <div class="asset-toolbar"><el-input v-model="keyword" clearable placeholder="搜索资料名称或文号" class="asset-search" @input="page = 1" /><el-select v-model="assetType" clearable placeholder="全部资料类型" @change="load"><el-option v-for="item in taxonomy.asset_types" :key="item.value" :label="item.label" :value="item.value" /></el-select><el-select v-model="ingestionState" clearable placeholder="全部处理状态" @change="load"><el-option v-for="(label, value) in ingestionLabels" :key="value" :label="label" :value="value" /></el-select><el-button v-if="canMaintain" type="primary" :loading="confirmingSources" :disabled="!confirmableRows.length" @click="confirmFilteredSources">确认筛选资料可用（{{ confirmableRows.length }}）</el-button><el-button @click="load">刷新</el-button><span>{{ filteredRows.length }} 份资料</span></div>
    <DataState :error="error" :empty="!loading && !filteredRows.length" empty-title="没有符合条件的资料" empty-description="调整搜索条件，或添加正文和附件开始整理。" @retry="load">
      <el-table :data="pagedRows" size="small" border @row-click="openDetail"><el-table-column label="资料名称" min-width="320"><template #default="{ row }"><button class="asset-name" @click.stop="openDetail(row)">{{ row.title }}</button><div class="row-subtitle">{{ assetTypeLabel(row.asset_type) }} · {{ row.issue_no || row.business_code || '文号未知' }}</div></template></el-table-column><el-table-column prop="version_label" label="版本" width="80" /><el-table-column prop="document_count" label="文件数" width="80" align="right" /><el-table-column label="发布状态" width="105"><template #default="{ row }">{{ releaseLabel(row.release_state) }}</template></el-table-column><el-table-column label="内容处理" width="140"><template #default="{ row }"><span :class="['state', row.ingestion_state]">{{ ingestionLabel(row.ingestion_state) }}</span></template></el-table-column><el-table-column label="操作" width="90"><template #default="{ row }"><el-button text type="primary" @click.stop="openDetail(row)">查看资料</el-button></template></el-table-column></el-table>
      <el-pagination v-if="filteredRows.length > pageSize" class="asset-pagination" layout="total, prev, pager, next" :total="filteredRows.length" :page-size="pageSize" v-model:current-page="page" />
    </DataState>
    <el-drawer v-model="detailVisible" :title="detail?.title || '资料详情'" size="min(1120px, 94vw)">
      <div v-loading="detailLoading"><DataState :error="detailError" @retry="reloadDetail"><template v-if="detail && activeVersion">
        <div class="asset-detail-summary"><span>{{ assetTypeLabel(detail.asset_type) }}</span><span>{{ activeVersion.issue_no || detail.business_code || '文号未知' }}</span><el-select v-model="activeVersionId" size="small" @change="changeVersion"><el-option v-for="version in detail.versions" :key="version.version_id" :label="version.version_label" :value="version.version_id" /></el-select><span>{{ releaseLabel(activeVersion.release_state) }}</span><span :class="['state', activeVersion.ingestion_state]">{{ ingestionLabel(activeVersion.ingestion_state) }}</span></div>
        <p class="asset-status-explanation">{{ availabilityMessage }}</p>
        <div class="asset-section-toolbar"><span>文号：{{ activeVersion.issue_no || '未知' }} · 生效：{{ activeVersion.effective_date || '未知' }}</span><template v-if="editable"><el-button size="small" @click="editSource">补充信息（可选）</el-button><el-button size="small" :loading="submitting" @click="submitForReview">正式审核（可选）</el-button></template><el-button v-if="canActivate" type="primary" size="small" :loading="activating" @click="activateSource">{{ activeVersion.release_state === 'current' ? '确认来源可用' : '本人确认并启用' }}</el-button><el-button v-if="canMaintain && activeVersion.release_state === 'current'" size="small" @click="startRevision">建立修订稿</el-button><el-button v-if="isAdmin && activeVersion.release_state === 'pending_review'" size="small" @click="router.push({path:'/review',query:{tab:'asset',asset:detail.asset_id,version:activeVersion.version_id}})">进入审核中心</el-button></div>
        <el-alert v-if="canMaintain && activeVersion.activation_gate?.errors.length" :title="activeVersion.activation_gate.errors.join('；')" type="warning" :closable="false" class="publication-warning" /><el-alert v-if="activeVersion.release_state === 'rejected'" :title="`审核退回：${activeVersion.review_note || '请核对资料后重新提交'}`" type="warning" :closable="false" class="publication-warning" />
        <p v-if="activeVersion.source_confirmation" class="reading-note">来源确认：{{ activeVersion.source_confirmation.note }} · {{ activeVersion.source_confirmation.confirmed_at.slice(0,10) }}</p><p v-if="activeVersion.authority_gaps?.length" class="reading-note">文号、日期或责任信息尚有缺项，可按已确认来源使用；以后取得原始信息再补充。</p><el-tabs v-model="detailTab" @tab-change="onDetailTabChange">
          <el-tab-pane label="文件与附件" name="files"><div class="asset-section-toolbar"><span>{{ activeVersion.documents.length }} 个文件，正文和附件均保留独立来源。</span><el-button v-if="editable" size="small" :loading="parsingVersion" :disabled="!activeVersion.documents.length" @click="parseActiveVersion">处理全部文件</el-button></div><el-table :data="activeVersion.documents" size="small" border empty-text="该版本尚无文件"><el-table-column label="文件" min-width="280"><template #default="{ row }"><strong>{{ row.filename }}</strong><div class="row-subtitle">{{ documentRoleLabel(row.role) }} · {{ formatBytes(row.size_bytes) }} · {{ row.normative ? '规范依据' : row.mandatory ? '必备材料' : '辅助材料' }}</div></template></el-table-column><el-table-column label="内容状态" width="145"><template #default="{ row }"><span :class="['state', row.parse_status]">{{ parseLabel(row.parse_status) }}</span><div v-if="row.parse_disposition === 'metadata_only'" class="row-subtitle">仅保存文件信息</div></template></el-table-column><el-table-column label="操作" width="230"><template #default="{ row }"><el-button text type="primary" :disabled="!row.parse_run_id" @click="openContent(row)">阅读内容</el-button><el-button v-if="editable" text @click="editRole(row)">文件用途</el-button><el-button v-if="editable" text :loading="parsingDocumentId === row.document_id" @click="parseOne(row)">重新处理</el-button></template></el-table-column></el-table></el-tab-pane>
          <el-tab-pane label="内容阅读" name="content"><div class="asset-section-toolbar"><el-select v-model="selectedDocumentId" placeholder="选择要阅读的文件" filterable class="document-select" @change="loadContent(1)"><el-option v-for="doc in activeVersion.documents" :key="doc.document_id" :label="doc.filename" :value="doc.document_id" :disabled="!doc.parse_run_id" /></el-select><el-radio-group v-model="readingMode" size="small"><el-radio-button value="reading">阅读</el-radio-button><el-radio-button value="structure">结构与定位</el-radio-button></el-radio-group></div><div v-loading="contentLoading"><DataState :error="contentError" :empty="!contentLoading && !treeData.nodes.length" empty-title="暂无可阅读内容" :empty-description="selectedDocument?.parse_status === 'requires_ocr' ? '此文件缺少文字层。请在系统外完成文字识别后重新上传。' : '先选择文件；尚未处理的文件可返回文件列表处理。'" @retry="loadContent(treePage)"><template v-if="readingMode === 'reading'"><div class="reading-note">正文与表格保留独立原文定位，可返回文件列表核对组成材料。</div><div class="asset-reader"><article v-for="node in readableNodes" :key="node.node_id" class="reading-block"><h3 v-if="node.title || node.label">{{ [node.label, node.title].filter(Boolean).join(' ') }}</h3><div v-if="node.structure.values?.length" class="row-values"><span v-for="(value, index) in node.structure.values" :key="index">{{ value || '—' }}</span></div><p v-else-if="node.text">{{ node.text }}</p><small>{{ locator(node) }}</small></article><p v-if="!readableNodes.length" class="reading-note">本段以结构信息为主，可切换“结构与定位”查看，或翻到下一段。</p></div></template><el-table v-else :data="treeData.nodes" size="small" border row-key="node_id"><el-table-column label="类型" width="90"><template #default="{ row }">{{ nodeTypeLabel(row.node_type) }}</template></el-table-column><el-table-column label="内容" min-width="350"><template #default="{ row }"><strong>{{ [row.label, row.title].filter(Boolean).join(' ') }}</strong><p class="structure-text">{{ row.text }}</p></template></el-table-column><el-table-column label="原文定位" width="220"><template #default="{ row }">{{ locator(row) }}</template></el-table-column></el-table><el-pagination v-if="treeData.total > treePageSize" class="asset-pagination" layout="total, prev, pager, next" :page-size="treePageSize" :total="treeData.total" :current-page="treePage" @current-change="loadContent" /></DataState></div></el-tab-pane>
          <el-tab-pane label="处理记录" name="processing"><p class="reading-note">以下为各文件当前处理结果。必备文件可读后，由维护者本人确认来源可靠即可启用。</p><section v-for="doc in activeVersion.documents" :key="doc.document_id" class="processing-record"><div><strong>{{ doc.filename }}</strong><span :class="['state', doc.parse_status]">{{ parseLabel(doc.parse_status) }}</span></div><p>{{ processingMessage(doc) }}</p><p v-for="warning in doc.quality_report.warnings || []" :key="warning" class="processing-warning">{{ warning }}</p><dl><dt>内容段落</dt><dd>{{ doc.quality_report.node_count ?? '—' }}</dd><dt>可引用段落</dt><dd>{{ doc.quality_report.citable_count ?? '—' }}</dd></dl><el-collapse><el-collapse-item title="技术定位信息"><span class="snapshot-id">{{ doc.parse_run_id || '尚未生成处理快照' }}</span></el-collapse-item></el-collapse></section></el-tab-pane>
        </el-tabs>
      </template></DataState></div>
    </el-drawer>
    <el-dialog v-model="packageVisible" title="添加资料" width="min(860px, 94vw)"><p class="reading-note">同一制度的正文、附件和配套模板一并添加，建立后先作为草稿保存。</p><el-form :model="packageForm" label-width="90px"><div class="package-grid"><el-form-item label="资料名称" required><el-input v-model="packageForm.title" /></el-form-item><el-form-item label="资料类型" required><el-select v-model="packageForm.asset_type"><el-option v-for="item in taxonomy.asset_types" :key="item.value" :label="item.label" :value="item.value" /></el-select></el-form-item><el-form-item label="文号 / 编码"><el-input v-model="packageForm.business_code" placeholder="按正式发文填写，可稍后核对" /></el-form-item><el-form-item label="版本"><el-input v-model="packageForm.version_label" /></el-form-item><el-form-item label="业务领域"><el-input v-model="packageForm.domain" placeholder="可选，留空保留未分类" /></el-form-item></div><el-form-item label="组成文件" required><el-upload :file-list="packageFiles" multiple :auto-upload="false" :on-change="onPackageFiles" :on-remove="onPackageFiles"><el-button>选择正文与附件</el-button></el-upload></el-form-item></el-form><el-table v-if="packageFiles.length" :data="packageFiles" size="small" border><el-table-column prop="name" label="文件" min-width="220" show-overflow-tooltip /><el-table-column label="用途" width="160"><template #default="{ row }"><el-select v-model="row.role"><el-option v-for="item in taxonomy.document_roles" :key="item.value" :label="item.label" :value="item.value" /></el-select></template></el-table-column><el-table-column label="必备文件" width="90"><template #default="{ row }"><el-checkbox v-model="row.mandatory" /></template></el-table-column><el-table-column label="规范依据" width="90"><template #default="{ row }"><el-checkbox v-model="row.normative" /></template></el-table-column></el-table><p class="reading-note">请核对每个文件的用途。PDF须有完整文字层；设计源文件和压缩包可作为素材保存。</p><template #footer><el-button @click="packageVisible = false">取消</el-button><el-button type="primary" :loading="creatingPackage" @click="createPackage">保存资料草稿</el-button></template></el-dialog>
    <el-dialog v-model="sourceVisible" title="补充资料信息（可选）" width="560px"><el-form label-width="95px"><el-form-item label="正式文号"><el-input v-model="sourceForm.issue_no" placeholder="填写正式发文，不用资料标题代替" /></el-form-item><el-form-item label="发文机构"><el-input v-model="sourceForm.issuer" /></el-form-item><el-form-item label="生效日期"><el-date-picker v-model="sourceForm.effective_date" type="date" value-format="YYYY-MM-DD" /></el-form-item><el-form-item label="失效日期"><el-date-picker v-model="sourceForm.expiry_date" type="date" value-format="YYYY-MM-DD" clearable /></el-form-item><el-form-item label="责任部门"><el-select v-model="sourceForm.owner_org" clearable filterable placeholder="可选，未知时留空"><el-option v-for="org in orgUnits" :key="org.org_id" :label="`${org.name}（${org.path}）`" :value="org.org_id" /></el-select></el-form-item><el-form-item label="业务领域"><el-input v-model="sourceForm.domain" placeholder="可选，未知时保留未分类" /></el-form-item><el-form-item label="核对依据" required><el-input v-model="sourceForm.evidence_note" type="textarea" :rows="3" placeholder="填写所依据的原文位置或补充说明，无须取得部门证明" /></el-form-item></el-form><template #footer><el-button @click="sourceVisible=false">取消</el-button><el-button type="primary" :loading="savingSource" @click="saveSource">保存核对记录</el-button></template></el-dialog>
    <el-dialog v-model="roleVisible" title="核对文件用途" width="520px"><p class="reading-note">{{ roleDocument?.filename }}</p><el-form label-width="95px"><el-form-item label="文件用途"><el-select v-model="roleForm.role"><el-option v-for="item in taxonomy.document_roles" :key="item.value" :label="item.label" :value="item.value" /></el-select></el-form-item><el-form-item label="必备文件"><el-checkbox v-model="roleForm.mandatory">未完成处理时阻止发布</el-checkbox></el-form-item><el-form-item label="规范依据"><el-checkbox v-model="roleForm.normative">文件用于规范性引用</el-checkbox></el-form-item><el-form-item label="核对依据" required><el-input v-model="roleForm.evidence_note" type="textarea" :rows="3" /></el-form-item></el-form><template #footer><el-button @click="roleVisible=false">取消</el-button><el-button type="primary" :loading="savingRole" @click="saveRole">保存文件用途</el-button></template></el-dialog>
    <el-dialog v-model="advancedVisible" title="高级维护" width="560px"><p class="reading-note">供系统管理员检查复合资料迁移。执行操作会写入资产记录。</p><div class="advanced-tools"><section><strong>标杆资料检查</strong><p>核对二十个既有标杆资料是否齐全。</p><el-button @click="inspectBenchmarks">检查资料完整性</el-button></section><section><strong>从现行制度建立资料</strong><p>按既有制度与附件建立复合资料记录，执行前需确认。</p><el-button @click="migrateBenchmarks">建立标杆资料记录</el-button></section></div></el-dialog>
  </div>
</template>

<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { useRouter } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import type { UploadFile, UploadUserFile } from 'element-plus'
import PageHeader from '@/components/PageHeader.vue'
import DataState from '@/components/DataState.vue'
import { useUserStore } from '@/store/user'
import * as assetApi from '@/api/asset'
import { listOrgUnits } from '@/api/governance'
const user = useUserStore()
const router = useRouter()
const isAdmin = computed(() => user.role === 'R4')
const canMaintain = computed(() => ['R3','R4'].includes(user.role))
const loading = ref(false), error = ref(''), rows = ref<assetApi.AssetRow[]>([])
const keyword = ref(''), assetType = ref(''), ingestionState = ref(''), page = ref(1), pageSize = 15
const taxonomy = reactive<assetApi.AssetTaxonomy>({ asset_types: [], document_roles: [], node_types: [] })
const summary = reactive<assetApi.AssetSummary>({ assets: 0, versions: 0, documents: 0, content_nodes: 0, parse_states: {}, version_ingestion_states: {}, benchmark_target: 20 })
const filteredRows = computed(() => rows.value.filter(row => `${row.title} ${row.business_code}`.toLowerCase().includes(keyword.value.trim().toLowerCase())))
const pagedRows = computed(() => filteredRows.value.slice((page.value - 1) * pageSize, page.value * pageSize))
const pendingCount = computed(() => ['pending', 'processing', 'needs_review'].reduce((n, state) => n + (summary.version_ingestion_states[state] || 0), 0))
const ingestionLabels: Record<string, string> = { pending: '待处理', processing: '处理中', needs_review: '待核对', ready: '内容处理完成', blocked: '处理受阻', failed: '处理失败' }
const detailVisible = ref(false), detailLoading = ref(false), detailError = ref(''), detail = ref<assetApi.AssetDetail | null>(null), activeAssetId = ref(''), activeVersionId = ref(''), detailTab = ref('files')
const activeVersion = computed(() => detail.value?.versions.find(version => version.version_id === activeVersionId.value) || detail.value?.versions[0])
const editable = computed(() => canMaintain.value && ['draft','rejected'].includes(activeVersion.value?.release_state || ''))
const activating = ref(false), confirmingSources = ref(false)
const sourceNote = '我确认这些上传资料来源可靠，可用于制度咨询与办理准备'
const canActivate = computed(() => canMaintain.value && ['draft','rejected','pending_review','current'].includes(activeVersion.value?.release_state || '') && activeVersion.value?.ingestion_state === 'ready' && activeVersion.value?.source_verification !== 'maintainer')
const confirmableRows = computed(() => filteredRows.value.filter(row => ['current','pending_review'].includes(row.release_state) && row.ingestion_state === 'ready' && row.source_verification !== 'maintainer' && (!row.effective_date || row.effective_date <= todayIso()) && (!row.expiry_date || row.expiry_date >= todayIso())))
const sourceVisible = ref(false), savingSource = ref(false), submitting = ref(false), roleVisible = ref(false), savingRole = ref(false)
const orgUnits = ref<{org_id:string;name:string;path:string}[]>([])
const sourceForm = reactive({issue_no:'',issuer:'',effective_date:null as string|null,expiry_date:null as string|null,owner_org:null as string|null,domain:'',evidence_note:''})
const roleDocument = ref<assetApi.AssetDocument|null>(null), roleForm = reactive({role:'',mandatory:true,normative:true,evidence_note:''})
const availabilityMessage = computed(() => activeVersion.value?.ingestion_state !== 'ready' ? '部分必备文件尚未完成处理，暂不能作为完整的问答依据。请先查看文件状态并处理问题。' : activeVersion.value?.release_state === 'current' ? activeVersion.value.authority_verified ? `资料可用于制度咨询与办理准备，${activeVersion.value.source_verification === 'maintainer' ? '来源已由维护者本人确认' : '来源信息完整'}。未知信息仍保留未知。` : '资料内容可阅读，请本人确认来源可靠后用于制度咨询与办理准备。' : '内容处理已完成，本人确认来源可靠即可启用，无须等待部门审核。')
const selectedDocumentId = ref(''), selectedDocument = computed(() => activeVersion.value?.documents.find(doc => doc.document_id === selectedDocumentId.value))
const contentLoading = ref(false), contentError = ref(''), readingMode = ref('reading'), treePage = ref(1), treePageSize = 100
const treeData = ref<assetApi.DocumentTree>({ document_id: '', filename: '', total: 0, offset: 0, limit: treePageSize, nodes: [] })
const readableNodes = computed(() => treeData.value.nodes.filter(node => node.node_type !== 'table_cell' && node.node_type !== 'document' && (node.is_citable || ['chapter', 'section', 'sheet', 'table'].includes(node.node_type)) && (node.text || node.title || node.label)))
const parsingVersion = ref(false), parsingDocumentId = ref(''), packageVisible = ref(false), creatingPackage = ref(false), advancedVisible = ref(false)
type PackageFile = UploadUserFile & { raw?: File; role: string; mandatory: boolean; normative: boolean }
const packageFiles = ref<PackageFile[]>([])
const packageForm = reactive({ title: '', asset_type: 'regulation', business_code: '', version_label: 'v1', domain: '' })
function todayIso() { const now=new Date(); return `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')}` }
function assetTypeLabel(value: string) { return taxonomy.asset_types.find(item => item.value === value)?.label || value }
function documentRoleLabel(value: string) { return taxonomy.document_roles.find(item => item.value === value)?.label || value }
function ingestionLabel(value: string) { return ingestionLabels[value] || value }
function releaseLabel(value: string) { return ({ current: '现行版本', draft: '未发布草稿', pending_review: '待审核', rejected:'已退回', replaced: '已替代', repealed: '已废止' } as Record<string, string>)[value] || value }
function parseLabel(value: string) { return ({ pending: '待处理', running: '处理中', succeeded: '处理成功', needs_review: '待人工核对', requires_ocr: '缺少文字层', failed: '处理失败' } as Record<string, string>)[value] || value }
function nodeTypeLabel(value: string) { return ({ document: '文档', chapter: '章', section: '节', article: '条', paragraph: '段', item: '项', table: '表格', table_row: '表格行', table_cell: '单元格', sheet: '工作表', flow_step: '步骤', form_field: '字段' } as Record<string, string>)[value] || value }
function formatBytes(size: number) { return size >= 1048576 ? `${(size / 1048576).toFixed(1)} MB` : `${Math.max(1, Math.round(size / 1024))} KB` }
function locator(node: assetApi.ContentNode) { return [node.sheet_name, node.cell_range, node.source_page ? `第 ${node.source_page} 页` : '', node.source_locator].filter(Boolean).join(' · ') || '未提供定位' }
function processingMessage(doc: assetApi.AssetDocument) { return doc.parse_status === 'requires_ocr' ? '文件缺少可提取的文字层，请先在系统外完成文字识别后重新上传。' : doc.parse_status === 'failed' ? '未能提取完整内容，请核对文件格式与源文件后重新处理。' : doc.parse_status === 'succeeded' ? '已提取内容并保存原文定位，可由维护者本人确认来源后启用。' : doc.parse_status === 'needs_review' ? '已提取部分内容，存在结构或质量问题，需要人工核对。' : '尚未完成内容处理。' }
async function load() { loading.value = true; error.value = ''; try { const [s, list, words] = await Promise.all([assetApi.summary(), assetApi.list({ asset_type: assetType.value || undefined, ingestion_state: ingestionState.value || undefined }), assetApi.taxonomy()]); Object.assign(summary, s); rows.value = list; Object.assign(taxonomy, words); page.value = 1 } catch { error.value = '资料暂时无法读取，请重试。' } finally { loading.value = false } }
async function openDetail(row: assetApi.AssetRow) { activeAssetId.value = row.asset_id; activeVersionId.value = row.version_id; detailTab.value = 'files'; detail.value = null; detailVisible.value = true; await reloadDetail(); changeVersion() }
let detailRequest = 0
async function reloadDetail() { const request = ++detailRequest; const assetId = activeAssetId.value; detailLoading.value = true; detailError.value = ''; try { const data = await assetApi.detail(assetId); if (request === detailRequest) detail.value = data } catch { if (request === detailRequest) detailError.value = '资料详情读取失败，请重试。' } finally { if (request === detailRequest) detailLoading.value = false } }
function changeVersion() { ++contentRequest; contentLoading.value = false; contentError.value = ''; selectedDocumentId.value = activeVersion.value?.documents.find(doc => doc.parse_run_id)?.document_id || ''; treeData.value = { document_id: '', filename: '', total: 0, offset: 0, limit: treePageSize, nodes: [] }; if (detailTab.value === 'content') loadContent(1) }
function onDetailTabChange() { if (detailTab.value === 'content' && selectedDocumentId.value && !treeData.value.nodes.length) loadContent(1) }
async function openContent(doc: assetApi.AssetDocument) { selectedDocumentId.value = doc.document_id; detailTab.value = 'content'; await loadContent(1) }
let contentRequest = 0
async function loadContent(nextPage: number) { if (!selectedDocumentId.value) return; const request = ++contentRequest; contentLoading.value = true; contentError.value = ''; treePage.value = nextPage; try { const data = await assetApi.tree(selectedDocumentId.value, { offset: (nextPage - 1) * treePageSize, limit: treePageSize }); if (request === contentRequest) treeData.value = data } catch { if (request === contentRequest) contentError.value = '文件内容读取失败，请重试。' } finally { if (request === contentRequest) contentLoading.value = false } }
async function parseOne(doc: assetApi.AssetDocument) { try { await ElMessageBox.confirm(`重新处理“${doc.filename}”，会生成新的内容快照。继续吗？`, '重新处理文件', { confirmButtonText: '重新处理', cancelButtonText: '取消' }) } catch { return } parsingDocumentId.value = doc.document_id; try { const result = await assetApi.parseDocument(doc.document_id); result.status === 'succeeded' ? ElMessage.success('文件处理完成，仍需核对业务适用性') : ElMessage.warning(parseLabel(result.status)); await reloadDetail(); if (selectedDocumentId.value === doc.document_id) await loadContent(1); await load() } finally { parsingDocumentId.value = '' } }
async function parseActiveVersion() { if (!activeVersion.value) return; try { await ElMessageBox.confirm('将依次重新处理本版本全部文件；较大资料可能需要数分钟。继续吗？', '处理全部文件', { confirmButtonText: '开始处理', cancelButtonText: '取消' }) } catch { return } parsingVersion.value = true; try { const result = await assetApi.parseVersion(activeVersion.value.version_id); const problems = result.documents.filter(doc => doc.status !== 'succeeded').length; problems ? ElMessage.warning(`处理结束，${problems} 个文件需要进一步核对`) : ElMessage.success('文件处理完成，仍需资料审核'); await reloadDetail(); await load() } finally { parsingVersion.value = false } }
function inferRole(name: string) { if (/流程/.test(name)) return 'flowchart'; if (/模板/.test(name)) return 'template'; if (/表/.test(name) && /\.xlsx?$/i.test(name)) return 'form'; if (/附件/.test(name)) return 'normative_annex'; if (/\.pptx$/i.test(name)) return 'training'; if (/\.(ai|zip|rar|7z)$/i.test(name)) return 'raw_asset'; return 'normative_body' }
function onPackageFiles(_: UploadFile, list: UploadFile[]) { packageFiles.value = list.map(item => { const existing = packageFiles.value.find(row => row.uid === item.uid); if (existing) return existing; const role = inferRole(item.name); return { ...item, role, mandatory: !['training', 'raw_asset', 'reference'].includes(role), normative: ['normative_body', 'normative_annex', 'standard_table'].includes(role) } }) }
async function createPackage() { if (!packageForm.title.trim() || !packageFiles.value.length) { ElMessage.warning('请填写资料名称并选择文件'); return } creatingPackage.value = true; try { const form = new FormData(); packageFiles.value.forEach(doc => { if (doc.raw) form.append('files', doc.raw) }); Object.entries(packageForm).forEach(([key, value]) => form.append(key, key === 'domain' ? (value.trim() || '*') : value.trim())); form.append('manifest_json', JSON.stringify(packageFiles.value.map(({ role, mandatory, normative }) => ({ role, mandatory, normative })))); const result = await assetApi.createPackage(form); ElMessage.success('资料草稿已保存'); packageVisible.value = false; packageFiles.value = []; packageForm.title = ''; await load(); const row = rows.value.find(item => item.asset_id === result.asset_id); if (row) await openDetail(row) } finally { creatingPackage.value = false } }
async function inspectBenchmarks() { const result = await assetApi.migrateBenchmarks(true); ElMessage.success(`资料检查完成：找到 ${result.found}/${result.requested} 项，缺少 ${result.missing.length} 项`) }
async function editSource() { if(!detail.value || !activeVersion.value)return; orgUnits.value=await listOrgUnits(); Object.assign(sourceForm,{issue_no:activeVersion.value.issue_no || '',issuer:activeVersion.value.issuer || '',effective_date:activeVersion.value.effective_date || null,expiry_date:activeVersion.value.expiry_date || null,owner_org:activeVersion.value.owner_org || detail.value.owner_org,domain:(activeVersion.value.domain || detail.value.domain) === '*' ? '' : (activeVersion.value.domain || detail.value.domain),evidence_note:''});sourceVisible.value=true }
async function saveSource(){if(!activeVersion.value || !sourceForm.evidence_note.trim()){ElMessage.warning('请填写核对依据');return}savingSource.value=true;try{await assetApi.updateMetadata(activeVersion.value.version_id,{...sourceForm,domain:sourceForm.domain.trim() || '*'});sourceVisible.value=false;await reloadDetail();ElMessage.success('来源核对记录已保存')}finally{savingSource.value=false}}
function editRole(doc:assetApi.AssetDocument){roleDocument.value=doc;Object.assign(roleForm,{role:doc.role,mandatory:doc.mandatory,normative:doc.normative,evidence_note:''});roleVisible.value=true}
async function saveRole(){if(!activeVersion.value || !roleDocument.value || !roleForm.evidence_note.trim()){ElMessage.warning('请填写文件用途核对依据');return}savingRole.value=true;try{await assetApi.updateRole(activeVersion.value.version_id,roleDocument.value.document_id,{...roleForm});roleVisible.value=false;await reloadDetail();ElMessage.success('文件用途已更新')}finally{savingRole.value=false}}
async function submitForReview(){if(!activeVersion.value)return;if(activeVersion.value.publication_gate && !activeVersion.value.publication_gate.publishable){ElMessage.warning(`正式审核还需补充：${activeVersion.value.publication_gate.errors.join('；')}。也可使用本人确认直接启用。`);return}try{await ElMessageBox.confirm('提交后文件用途和内容将锁定，交由审核人员核对原文后发布。','提交资料审核',{confirmButtonText:'提交审核',cancelButtonText:'取消'})}catch{return}submitting.value=true;try{await assetApi.submitVersion(activeVersion.value.version_id);await reloadDetail();await load();ElMessage.success('已提交资料审核')}finally{submitting.value=false}}
async function activateSource(){if(!activeVersion.value)return;activating.value=true;try{await assetApi.activateVersion(activeVersion.value.version_id,sourceNote);await reloadDetail();await load();ElMessage.success('来源已由本人确认，资料已启用')}finally{activating.value=false}}
async function confirmFilteredSources(){const candidates=[...confirmableRows.value];if(!candidates.length)return;try{await ElMessageBox.confirm(`我确认当前筛选的 ${candidates.length} 份资料来源可靠，可用于制度咨询与办理准备。文号、日期和部门缺项保留未知。`,'本人确认来源',{confirmButtonText:'确认来源可用',cancelButtonText:'取消'})}catch{return}confirmingSources.value=true;let count=0;try{for(let i=0;i<candidates.length;i+=2000){const result=await assetApi.confirmSources(candidates.slice(i,i+2000).map(row=>row.version_id),sourceNote);count+=result.count}ElMessage.success(`已确认 ${count} 份资料来源可用`);await load()}finally{confirmingSources.value=false}}
async function startRevision(){if(!activeVersion.value)return;let label='';try{const result=await ElMessageBox.prompt('填写新版本名称。修订稿有独立文件和处理记录，原发布版本继续保留。','建立修订稿',{confirmButtonText:'建立修订稿',cancelButtonText:'取消',inputValidator:value=>!!value?.trim() || '请填写版本名称'});label=result.value.trim()}catch{return}const result=await assetApi.createRevision(activeVersion.value.version_id,label);activeVersionId.value=result.version_id;await reloadDetail();changeVersion();await load();ElMessage.success('修订稿已建立，请核对来源并处理组成文件')}
async function migrateBenchmarks() { try { await ElMessageBox.confirm('将在复合资料库中建立标杆资料记录。此操作会写入数据库，请确认当前资料清单后继续。', '建立标杆资料记录', { type: 'warning', confirmButtonText: '确认建立', cancelButtonText: '取消' }) } catch { return } const result = await assetApi.migrateBenchmarks(false); ElMessage.success(`已建立 ${result.version_ids?.length || 0} 个资料版本`); await load() }
onMounted(load)
</script>

