.asset-status-strip { display:flex; flex-wrap:wrap; gap:28px; padding:13px 16px; background:#fff; border:1px solid var(--zg-border); margin-bottom:16px; font-size:13px; color:var(--zg-text-secondary); }.asset-status-strip b { margin-left:8px; color:var(--zg-text); }.asset-status-strip .danger { color:#a33b32; }.asset-toolbar,.asset-section-toolbar { display:flex; flex-wrap:wrap; gap:10px; align-items:center; margin-bottom:14px; }.asset-toolbar>.el-select { width:165px; }.asset-toolbar>span { margin-left:auto; color:var(--zg-text-secondary); font-size:12px; }.asset-search { width:280px; }.asset-name { padding:0; border:0; background:none; color:var(--zg-primary); text-align:left; cursor:pointer; font:inherit; font-weight:600; line-height:1.55; }.row-subtitle { margin-top:5px; color:var(--zg-text-secondary); font-size:12px; line-height:1.5; }.asset-pagination { justify-content:flex-end; margin-top:16px; }.state { font-size:12px; color:var(--zg-text-secondary); }.state.ready,.state.succeeded { color:#397553; }.state.needs_review { color:#986916; }.state.failed,.state.blocked,.state.requires_ocr { color:#a33b32; }.asset-detail-summary { display:flex; flex-wrap:wrap; align-items:center; gap:16px; font-size:12px; color:var(--zg-text-secondary); }.asset-detail-summary .el-select { width:100px; }.asset-status-explanation { margin:14px 0 20px; padding:10px 12px; background:var(--zg-panel-soft); border-left:3px solid var(--zg-primary); font-size:12px; line-height:1.7; }.asset-section-toolbar>span { font-size:12px; color:var(--zg-text-secondary); margin-right:auto; }.document-select { flex:1; min-width:240px; }.reading-note { color:var(--zg-text-secondary); font-size:12px; line-height:1.7; margin:0 0 14px; }.asset-reader { padding:10px 26px; border:1px solid var(--zg-border); background:#fff; }.reading-block { padding:15px 0; border-bottom:1px solid var(--zg-border-light); }.reading-block:last-child { border-bottom:0; }.reading-block h3 { margin:0 0 8px; font-size:14px; color:var(--zg-text); }.reading-block p { white-space:pre-wrap; line-height:1.9; margin:0 0 8px; font-size:14px; }.reading-block small { display:block; color:var(--zg-text-weak); font-size:11px; overflow-wrap:anywhere; }.row-values { display:flex; overflow-x:auto; border:1px solid var(--zg-border); margin-bottom:8px; }.row-values span { flex:1; min-width:90px; padding:9px; border-right:1px solid var(--zg-border); line-height:1.7; font-size:12px; }.row-values span:last-child { border-right:0; }.structure-text { margin:5px 0 0; white-space:pre-wrap; line-height:1.7; }.processing-record { border:1px solid var(--zg-border); padding:14px 16px; margin-bottom:12px; }.processing-record>div:first-child { display:flex; justify-content:space-between; gap:16px; }.processing-record>p { font-size:12px; color:var(--zg-text-secondary); line-height:1.7; }.processing-record .processing-warning { color:#986916; }.processing-record dl { display:flex; gap:12px; font-size:12px; color:var(--zg-text-secondary); }.processing-record dd { margin:0 18px 0 0; color:var(--zg-text); }.snapshot-id { overflow-wrap:anywhere; font-size:11px; color:var(--zg-text-weak); }.package-grid { display:grid; grid-template-columns:1fr 1fr; gap:0 12px; }.package-grid .el-select { width:100%; }.advanced-tools section { padding:14px 0; border-top:1px solid var(--zg-border); }.advanced-tools p { font-size:12px; color:var(--zg-text-secondary); line-height:1.7; }@media(max-width:700px) { .asset-search { width:100%; }.asset-toolbar>.el-select { flex:1; min-width:140px; }.asset-reader { padding:6px 12px; }.package-grid { grid-template-columns:1fr; } }
.publication-warning { margin-bottom:14px; }
